                cache_write: number;
                /** @description Completed, escalated runs included: one completed and waits for a person's review. */
                completed: number;
                /** @description The sum of the known costs, rounded to 1e-6; null when no run's cost is known, never 0 for unknown. */
                cost_usd: number | null;
                /** @description Failed: never an escalated run. */
                failed: number;
                input: number;
                /** @description Of `completed`, the escalated runs, which wait for a person's review. */
                needs_review: number;
                output: number;
                /** @description Model requests. */
                requests: number;
                runs: number;
                /** @description Of `runs`, those that ended with metrics: a running run, and a run whose end wrote none, has none. */
                runs_with_metrics: number;
                /** @description Input, cache read, cache write and output tokens, summed over `runs_with_metrics`. */
                tokens: number;
                /** @description Runs with no known cost: running, or ended without one. */
                unknown_cost_runs: number;
